//! 🧫️ Shared glyph scenes retain authored semantic owners and match independent font contours.
use super::*;
use crate::{FillRule,FillStyle,schema::scene_preparation::DocumentSceneNode};
use semio_framework_value::{retirement::controlled::ControlledRetirement,retained_clone::RetainedCloneGrant};
fn close<T:RetireOwned>(value:T){let mut owner=ControlledRetirement::new(value).unwrap_or_else(|(error,_)|panic!("{error}"));for _ in 0..2_000_000{if owner.terminal_is_empty(){break;}let copy=owner.next_copy_byte_demand().unwrap();let release=owner.next_release_byte_demand().unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(if copy==0{release}else{copy}).unwrap(),maximum_release_bytes:release,maximum_depth:owner.next_depth_demand().unwrap()};let(zero,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(RetainedCloneGrant{maximum_items:0,..grant}).unwrap());assert!(!physical.overflowed);assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert_eq!(zero.progress(),Default::default());let(step,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(grant).unwrap());assert!(!physical.overflowed);assert!(step.progress().fits(grant));assert_eq!(physical.requested_bytes,step.progress().retained_capacity_bytes);assert_eq!(physical.released_bytes,step.progress().released_bytes);}assert!(owner.terminal_is_empty());let(_,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));}
fn plan(row:&serde_json::Value)->DocumentScenePlan{DocumentScenePlan{assets:Vec::new(),nodes:vec![DocumentSceneNode{source_path:vec![0],locked_ancestors:0,id:row["name"].as_str().unwrap().into(),groups:Vec::new(),transform:serde_json::from_value(row["transform"].clone()).unwrap(),opacity:1.0,blend_mode:"normal".into(),visible:true,content:DocumentSceneContent::Text{font_family:crate::DrawingFontFamily::parse(row["fontFamily"].as_str().unwrap()).unwrap(),content:row["content"].as_str().unwrap().into(),x:row["x"].as_f64().unwrap(),y:row["y"].as_f64().unwrap(),size:row["size"].as_f64().unwrap(),fill_rule:FillRule::Nonzero,fill:Some(serde_json::from_value::<FillStyle>(row["fill"].clone()).unwrap()),stroke:None}}]}}
struct Oracle<'a>{path:&'a mut tiny_skia::PathBuilder,origin:[f64;2],scale:f64}
struct Count(usize);
impl ttf_parser::OutlineBuilder for Count{fn move_to(&mut self,_:f32,_:f32){self.0+=1;}fn line_to(&mut self,_:f32,_:f32){self.0+=1;}fn quad_to(&mut self,_:f32,_:f32,_:f32,_:f32){self.0+=1;}fn curve_to(&mut self,_:f32,_:f32,_:f32,_:f32,_:f32,_:f32){self.0+=1;}fn close(&mut self){self.0+=1;}}
#[test]
fn document_text_aggregate_segments_refuse_partial_scene_publication(){let contract:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/📏️limits/🔣️.json")).unwrap();let rows:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let mut row=rows[0].clone();let text=contract["content"].as_str().unwrap().repeat(contract["repetitions"].as_u64().unwrap()as usize);row["content"]=text.clone().into();let font=semio_framework_2d::text::font::catalog::FONT_SOURCES.iter().find(|source|source.family=="Anta"&&source.id=="latin").unwrap();let parser=ttf_parser::Face::parse(font.bytes.0,0).unwrap();let mut count=Count(0);for scalar in text.chars(){parser.outline_glyph(parser.glyph_index(scalar).unwrap(),&mut count);}let nodes=contract["nodes"].as_u64().unwrap()as usize;let limit=contract["maxSegments"].as_u64().unwrap()as usize;assert!(count.0<limit);assert!(count.0*nodes>limit);let mut source=DocumentScenePlan{assets:Vec::new(),nodes:Vec::new()};for _ in 0..nodes{source.nodes.extend(plan(&row).nodes);}let mut job=DocumentTextJob::new(source,1000000000);loop{match job.advance(4096){Ok(progress)=>assert!(!progress.done,"Aggregate scene overflow must refuse"),Err(error)=>{assert!(error.to_string().contains("Text scene segment limit exceeded"));break;}}}let original=job.owners.plan.as_ref().unwrap();assert!(original.nodes.iter().any(|node|matches!(node.content,DocumentSceneContent::Glyphs{..})));assert!(original.nodes.iter().any(|node|matches!(node.content,DocumentSceneContent::Text{..})));let(retirement,output)=job.into_retirement();assert!(output.is_none());close(retirement);eprintln!("[DEBUG] Native independent ttf-parser {} segments/run establish scene overflow; partial glyphs and originals close under exact physical grants",count.0);}
impl Oracle<'_>{fn map(&self,x:f32,y:f32)->[f32;2]{[(self.origin[0]+f64::from(x)*self.scale)as f32,(self.origin[1]-f64::from(y)*self.scale)as f32]}}
impl ttf_parser::OutlineBuilder for Oracle<'_>{fn move_to(&mut self,x:f32,y:f32){let p=self.map(x,y);self.path.move_to(p[0],p[1]);}fn line_to(&mut self,x:f32,y:f32){let p=self.map(x,y);self.path.line_to(p[0],p[1]);}fn quad_to(&mut self,a:f32,b:f32,x:f32,y:f32){let c=self.map(a,b);let p=self.map(x,y);self.path.quad_to(c[0],c[1],p[0],p[1]);}fn curve_to(&mut self,a:f32,b:f32,c:f32,d:f32,x:f32,y:f32){let a=self.map(a,b);let b=self.map(c,d);let p=self.map(x,y);self.path.cubic_to(a[0],a[1],b[0],b[1],p[0],p[1]);}fn close(&mut self){self.path.close();}}
fn render(path:Option<tiny_skia::Path>,row:&serde_json::Value)->tiny_skia::Pixmap{let mut pixels=tiny_skia::Pixmap::new(row["width"].as_u64().unwrap()as u32,row["height"].as_u64().unwrap()as u32).unwrap();let matrix:[f64;6]=serde_json::from_value(row["transform"].clone()).unwrap();if let Some(path)=path{pixels.fill_path(&path,&tiny_skia::Paint::default(),tiny_skia::FillRule::Winding,tiny_skia::Transform::from_row(matrix[0]as f32,matrix[1]as f32,matrix[2]as f32,matrix[3]as f32,matrix[4]as f32,matrix[5]as f32),None);}pixels}
#[test]
fn document_text_shared_original_glyphs_match_independent_contours(){let rows:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();for row in rows.as_array().unwrap(){let family=crate::DrawingFontFamily::parse(row["fontFamily"].as_str().unwrap()).unwrap();let source=semio_framework_2d::text::font::catalog::FONT_SOURCES.iter().find(|source|source.family==family.catalog_family()&&if let Some(id)=row["oracleFace"].as_str(){source.id==id}else{row["content"].as_str().unwrap().chars().filter(|scalar|!matches!(scalar,'\r'|'\n')).all(|scalar|ttf_parser::Face::parse(source.bytes.0,0).unwrap().glyph_index(scalar).is_some())}).unwrap().bytes.0;let parser=ttf_parser::Face::parse(source,0).unwrap();let shaper=rustybuzz::Face::from_slice(source,0).unwrap();let text=row["oracleText"].as_str().unwrap_or(row["content"].as_str().unwrap()).replace("\r\n","\n").replace('\r',"\n");let size=row["size"].as_f64().unwrap();let scale=size/f64::from(parser.units_per_em());let mut reference=tiny_skia::PathBuilder::new();for(line,text)in text.split('\n').enumerate(){let mut buffer=rustybuzz::UnicodeBuffer::new();buffer.push_str(text);buffer.guess_segment_properties();if row["oracleDirection"].as_str()==Some("rtl"){buffer.set_direction(rustybuzz::Direction::RightToLeft);}let shaped=rustybuzz::shape(&shaper,&[],buffer);let mut x=row["x"].as_f64().unwrap();let y=row["y"].as_f64().unwrap()+size+line as f64*size*1.2;for(info,position)in shaped.glyph_infos().iter().zip(shaped.glyph_positions()){parser.outline_glyph(ttf_parser::GlyphId(info.glyph_id as u16),&mut Oracle{path:&mut reference,origin:[x+f64::from(position.x_offset)*scale,y-f64::from(position.y_offset)*scale],scale});x+=f64::from(position.x_advance)*scale;}}let expected=render(reference.finish(),row);for grant in [1,7,4096]{let input=plan(row);let DocumentSceneContent::Text{content,..}=&input.nodes[0].content else{panic!()};let pointer=content.as_ptr();let mut job=DocumentTextJob::new(input,1000000000);let mut work=0;while !job.result().is_ok(){let progress=job.advance(grant).unwrap();assert!(progress.work-work<=grant as u64);work=progress.work;}let(mut retirement,output)=job.into_retirement();let output=output.unwrap();let DocumentSceneContent::Glyphs{content,segments,..}=&output.nodes[0].content else{panic!("resolved glyph path required")};assert_eq!(content.as_ptr(),pointer);assert_eq!(content,row["content"].as_str().unwrap());let views=crate::schema::scene_view::nodes(&output,None).unwrap();assert_eq!(views[0].segments.as_ptr(),segments.as_ptr());assert!(views[0].bounds().is_some());let mut actual=tiny_skia::PathBuilder::new();for segment in segments{match segment{PathSegment::Move{to}=>actual.move_to(to[0]as f32,to[1]as f32),PathSegment::Line{to}=>actual.line_to(to[0]as f32,to[1]as f32),PathSegment::Quad{ctrl,to}=>actual.quad_to(ctrl[0]as f32,ctrl[1]as f32,to[0]as f32,to[1]as f32),PathSegment::Close=>actual.close(),_=>panic!("true quadratic glyph required")}}let actual=render(actual.finish(),row);assert!(actual.data().iter().zip(expected.data()).all(|(a,b)|a.abs_diff(*b)<=1));crate::draw_scene_physical_close!(retirement,1);close(retirement);close(output);eprintln!("[DEBUG] Native shared glyph scene {} grant={grant}: original semantic pointer, rustybuzz positions, ttf-parser contours and funded physical close",row["name"]);}}}
#[test]
fn document_text_cancelled_public_phases_keep_original_private_owners(){let rows:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();for phase in ["nodes","fonts","run","geometryAdmission","geometry","publishing","complete"]{let mut job=DocumentTextJob::new(plan(&rows[0]),1000000000);for _ in 0..1_000_000{let progress=job.advance(1).unwrap();if progress.phase==phase{break;}}job.cancel();assert!(job.result().is_err());let(retirement,output)=job.into_retirement();assert!(output.is_none());close(retirement);eprintln!("[DEBUG] Native text cancellation phase={phase}: original plan and every completed font/glyph owner retired under exact physical grants");}}
